def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate):
        return np.clip(candidate, lb, ub)

    best_x = np.zeros(dim)
    best_f = float('inf')

    for _ in range(budget):
        x = np.random.uniform(lb, ub, size=dim)
        f = func(x)

        if f < best_f:
            best_f = f
            best_x = clip(x)

    return best_x

def algorithm(func, dim, lb, ub, budget, rng):
    x_best = np.zeros(dim)
    f_best = float('inf')
    step_size = 1.0
    for _ in range(budget):
        if rng.random() < 0.5:
            std_dev = rng.uniform(0.01, 0.1)
            x_candidate = x_best + rng.normal(0, std_dev, dim) * np.clip(step_size, 0.1, 10.0)
        else:
            alpha = rng.uniform(-1.0, 1.0)
            x_candidate = x_best + alpha * (ub - lb)

        f_candidate = func(x_candidate)

        if f_candidate < f_best:
            f_best = f_candidate
            x_best = np.clip(x_candidate, lb, ub)

    return x_best
